header_re=re.compile(r'^([a-z]+)(?:\(([^()\s]+)\))?(!)?: (.+)$')
revert_line_re=re.compile(r'^This reverts commit ([0-9a-f]+)\.$')
fix_re=re.compile(r'^Fixes #(\d+)$')

# Commits named by a revert.
reverted=set()
for r in rows:
    lines=r['message'].splitlines()
    if lines and lines[0].startswith('Revert "'):
        for line in lines[1:]:
            m=revert_line_re.match(line)
            if m:
                reverted.add(m.group(1))

included=[]
for r in rows:
    lines=r['message'].splitlines()
    if not lines:
        continue
    head=lines[0]
    if head.startswith('Revert "'):
        continue
    m=header_re.match(head)
    if not m:
        continue
    typ, scope, bang, summary=m.groups()
    if r['hash'] in reverted:
        continue
    scope=scope or 'general'
    if scope=='deps':
        scope='dependencies'
    breaking=bool(bang)
    if not breaking and typ not in ('feat','fix','perf'):
        continue
    if scope=='internal' and not breaking:
        continue
    if breaking:
        section='Breaking changes'
    elif typ=='feat':
        section='Features'
    elif typ=='fix':
        section='Fixes'
    else:  # perf
        section='Features'
    s=summary
    s=s[0].upper()+s[1:]
    if s.endswith('.'):
        s=s[:-1]
    if typ=='perf' and not breaking:
        s+=' [perf]'
    refs=[]
    if typ=='fix':
        for line in lines[1:]:
            fm=fix_re.match(line)
            if fm:
                refs.append(fm.group(1))
    included.append({
        'hash': r['hash'],
        'author': r['author'],
        'email': r['email'],
        'dt': datetime.fromisoformat(r['date']),
        'message': r['message'],
        'type': typ,
        'scope': scope,
        'summary': s,
        'refs': refs,
        'section': section,
    })

# Group for merging.
groups=collections.defaultdict(list)
for e in included:
    groups[(e['section'], e['scope'], e['summary'])].append(e)

def build_entry(commits):
    commits=sorted(commits, key=lambda e: e['dt'], reverse=True)
    scope=commits[0]['scope']
    summary=commits[0]['summary']
    refs=[]
    for e in commits:
        for n in e['refs']:
            if n not in refs:
                refs.append(n)
    hashes=[e['hash'][:7] for e in commits]
    base=f"- **{scope}:** {summary}"
    refs_part=''.join(f" (#{n})" for n in refs)
    hashes_part=f" ({', '.join(hashes)})"
    line=base+refs_part+hashes_part
    if len(line)>100:
        fixed=len(line)-len(summary)
        limit=100-fixed-1
        prefix=summary[:limit].rstrip(' ')
        summary=prefix+'…'
        line=f"- **{scope}:** {summary}"+refs_part+hashes_part
    return line

section_order=['Breaking changes','Features','Fixes']
section_entries={}
for section in section_order:
    gs=[v for k,v in groups.items() if v[0]['section']==section]
    gs.sort(key=lambda v: (v[0]['scope'], -max(e['dt'].timestamp() for e in v)))
    section_entries[section]=[build_entry(v) for v in gs]

