for e in included:
    people=set()
    an=mailmap.get(e['email'], e['author'])
    people.add(an)
    authored.add(an)
    for line in e['message'].splitlines()[1:]:
        cm=coauthor_re.match(line)
        if cm:
            cn=mailmap.get(cm.group(2), cm.group(1).strip())
            people.add(cn)
    for p in people:
        counts[p]+=1

contributors=[]
