        contributors.append((name,n))
contributors.sort(key=lambda x:(-x[1], x[0]))

blocks=[]
for section in section_order:
    entries=section_entries[section]
    if entries:
        blocks.append('## '+section+'\n\n'+'\n'.join(entries))
if contributors:
    blocks.append('## Contributors\n\n'+'\n'.join(f'- {name} ({n})' for name,n in contributors))
out='# Release 4.2.0\n\n'+'\n\n'.join(blocks)+'\n'
print(out)
print('--- stats')
print('included',len(included),'groups',sum(len(v) for v in section_entries.values()))
print('max line length',max(len(l) for l in out.splitlines()))
print('long lines:')
for l in out.splitlines():
